// Applicator keywords: allOf, anyOf, oneOf, not, if/then/else,
// unevaluatedProperties, unevaluatedItems.
//
// Error-counting behavior verified against the reference executable
// (modern jsonschema 4.x semantics):
//   - allOf: concatenation of the descend errors of EVERY branch
//     (valid branches contribute nothing because descend returns []).
//   - anyOf: ONE single error when no branch is valid (sub-errors live in
//     Python's error.context and are NOT counted by iter_errors).
//   - oneOf: ONE single error both when 0 branches are valid and when
//     2+ branches are valid; [] when exactly one is valid.
//   - not: ONE error when the instance IS valid against the subschema.
//   - if/then/else: `if` alone yields nothing; `then` applies only when
//     `if` is present and the instance is valid against it; `else` only
//     when `if` is present and the instance is invalid against it.
//   - unevaluatedProperties / unevaluatedItems: at most ONE error total,
//     no matter how many properties/items are unevaluated or fail
//     (verified: 3 failing unevaluated items -> exactly 1 error).
//
// LIMITATION (unevaluated*): real annotation tracking is not available
// through ctx, so "evaluated" keys/indexes are approximated by a STATIC
// walk of the current schema object, mirroring jsonschema's
// find_evaluated_property_keys / find_evaluated_item_indexes:
//   - recurses into all allOf/anyOf/oneOf branches (unconditionally),
//   - recurses into `if` + taken `then`/`else` branch,
//   - properties/patternProperties match unconditionally (a FAILING
//     properties subschema still marks the key evaluated - verified),
//   - additionalProperties: `true` evaluates all remaining keys, a schema
//     evaluates a remaining key only if the value is valid against it
//     (verified: failing additionalProperties leaves the key unevaluated),
//     `false` evaluates nothing,
//   - prefixItems/items mark indexes unconditionally (verified: a failing
//     items schema still marks the indexes evaluated),
//   - contains marks the indexes it matches,
//   - $ref is NOT followed (resolution belongs to the engine and no
//     resolver is exposed through ctx).

import { makeError } from "../errors.mjs";

function isPlainObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function allOf(ctx, value, instance, schema) {
  const errors = [];
  for (let i = 0; i < value.length; i++) {
    errors.push(...ctx.descend(instance, value[i], [], ["allOf", i]));
  }
  return errors;
}

function anyOf(ctx, value, instance, schema) {
  for (const subschema of value) {
    if (ctx.isValid(instance, subschema)) return [];
  }
  return [makeError([], ["anyOf"])];
}

function oneOf(ctx, value, instance, schema) {
  let validCount = 0;
  for (const subschema of value) {
    if (ctx.isValid(instance, subschema)) validCount++;
  }
  if (validCount === 1) return [];
  return [makeError([], ["oneOf"])];
}

function not(ctx, value, instance, schema) {
  if (ctx.isValid(instance, value)) return [makeError([], ["not"])];
  return [];
}

// `if` never produces errors itself; it only steers then/else.
function ifKeyword(ctx, value, instance, schema) {
  return [];
}

function then(ctx, value, instance, schema) {
  if (!("if" in schema)) return [];
  if (ctx.isValid(instance, schema["if"])) {
    return ctx.descend(instance, value, [], ["then"]);
  }
  return [];
}

function elseKeyword(ctx, value, instance, schema) {
  if (!("if" in schema)) return [];
  if (!ctx.isValid(instance, schema["if"])) {
    return ctx.descend(instance, value, [], ["else"]);
  }
  return [];
}

// --- unevaluated* helpers (best-effort static annotation walk) ----------

function findEvaluatedPropertyKeys(ctx, instance, schema, evaluated) {
  if (!isPlainObject(schema)) return evaluated;

  for (const combiner of ["allOf", "anyOf", "oneOf"]) {
    const subs = schema[combiner];
    if (Array.isArray(subs)) {
      for (const sub of subs) {
        findEvaluatedPropertyKeys(ctx, instance, sub, evaluated);
      }
    }
  }

  if ("if" in schema) {
    if (ctx.isValid(instance, schema["if"])) {
      findEvaluatedPropertyKeys(ctx, instance, schema["if"], evaluated);
      if ("then" in schema) {
        findEvaluatedPropertyKeys(ctx, instance, schema.then, evaluated);
      }
    } else if ("else" in schema) {
      findEvaluatedPropertyKeys(ctx, instance, schema["else"], evaluated);
    }
  }

  const props = isPlainObject(schema.properties) ? schema.properties : null;
  const patterns = isPlainObject(schema.patternProperties)
    ? Object.keys(schema.patternProperties).map((p) => new RegExp(p))
    : [];

  if (props) {
    for (const key of Object.keys(props)) {
      if (key in instance) evaluated.add(key);
    }
  }
  for (const re of patterns) {
    for (const key of Object.keys(instance)) {
      if (re.test(key)) evaluated.add(key);
    }
  }

  if ("additionalProperties" in schema) {
    const ap = schema.additionalProperties;
    for (const key of Object.keys(instance)) {
      if (evaluated.has(key)) continue;
      if (props && key in props) continue;
      if (patterns.some((re) => re.test(key))) continue;
      if (ap === true) {
        evaluated.add(key);
      } else if (isPlainObject(ap) && ctx.isValid(instance[key], ap)) {
        evaluated.add(key);
      }
    }
  }

  return evaluated;
}

function findEvaluatedItemIndexes(ctx, instance, schema, evaluated) {
  if (!isPlainObject(schema)) return evaluated;

  for (const combiner of ["allOf", "anyOf", "oneOf"]) {
    const subs = schema[combiner];
    if (Array.isArray(subs)) {
      for (const sub of subs) {
        findEvaluatedItemIndexes(ctx, instance, sub, evaluated);
      }
    }
  }

  if ("if" in schema) {
    if (ctx.isValid(instance, schema["if"])) {
      findEvaluatedItemIndexes(ctx, instance, schema["if"], evaluated);
      if ("then" in schema) {
        findEvaluatedItemIndexes(ctx, instance, schema.then, evaluated);
      }
    } else if ("else" in schema) {
      findEvaluatedItemIndexes(ctx, instance, schema["else"], evaluated);
    }
  }

  if (Array.isArray(schema.prefixItems)) {
    for (let i = 0; i < schema.prefixItems.length; i++) evaluated.add(i);
  }

  if ("items" in schema) {
    const items = schema.items;
    if (Array.isArray(items)) {
      // draft2019 array form: indexes covered by the tuple...
      for (let i = 0; i < items.length; i++) evaluated.add(i);
      // ...and additionalItems governs the rest (like additionalProperties)
      if ("additionalItems" in schema) {
        const ai = schema.additionalItems;
        for (let i = items.length; i < instance.length; i++) {
          if (ai === true) {
            evaluated.add(i);
          } else if (isPlainObject(ai) && ctx.isValid(instance[i], ai)) {
            evaluated.add(i);
          }
        }
      }
    } else if (items === true || isPlainObject(items)) {
      // schema form: applies to (and therefore evaluates) every index,
      // even when the item fails validation (verified against reference).
      for (let i = 0; i < instance.length; i++) evaluated.add(i);
    }
  }

  if ("contains" in schema) {
    for (let i = 0; i < instance.length; i++) {
      if (ctx.isValid(instance[i], schema.contains)) evaluated.add(i);
    }
  }

  return evaluated;
}

function unevaluatedProperties(ctx, value, instance, schema) {
  if (!isPlainObject(instance)) return [];
  const evaluated = findEvaluatedPropertyKeys(ctx, instance, schema, new Set());
  const unevaluated = Object.keys(instance).filter((k) => !evaluated.has(k));
  if (unevaluated.length === 0) return [];
  if (value === false) return [makeError([], ["unevaluatedProperties"])];
  if (value === true) return [];
  // schema value: a single error if ANY unevaluated property is invalid
  // (verified against the reference executable).
  for (const key of unevaluated) {
    if (!ctx.isValid(instance[key], value)) {
      return [makeError([], ["unevaluatedProperties"])];
    }
  }
  return [];
}

function unevaluatedItems(ctx, value, instance, schema) {
  if (!Array.isArray(instance)) return [];
  const evaluated = findEvaluatedItemIndexes(ctx, instance, schema, new Set());
  const unevaluated = [];
  for (let i = 0; i < instance.length; i++) {
    if (!evaluated.has(i)) unevaluated.push(i);
  }
  if (unevaluated.length === 0) return [];
  if (value === false) return [makeError([], ["unevaluatedItems"])];
  if (value === true) return [];
  for (const i of unevaluated) {
    if (!ctx.isValid(instance[i], value)) {
      return [makeError([], ["unevaluatedItems"])];
    }
  }
  return [];
}

export const keywords = {
  allOf,
  anyOf,
  oneOf,
  not,
  if: ifKeyword,
  then,
  else: elseKeyword,
  unevaluatedProperties,
  unevaluatedItems,
};

export class ValidationError {
  constructor(path = [], schemaPath = []) {
    this.path = path;
    this.schemaPath = schemaPath;
  }
}
export function makeError(path = [], schemaPath = []) {
  return { path, schemaPath };
}

// Mini mock engine to exercise /output/lib/keywords/applicator.mjs without
// the real engine. Supports just enough keywords to reproduce the probes.
import { keywords } from "/output/lib/keywords/applicator.mjs";

function isPlainObject(v) {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}
function isNumber(v) { return typeof v === "number"; }
function isInteger(v) { return isNumber(v) && Number.isInteger(v); }

const simple = {
  type(ctx, value, instance) {
    const ok = {
      string: (i) => typeof i === "string",
      number: isNumber,
      integer: isInteger,
      object: isPlainObject,
      array: Array.isArray,
      boolean: (i) => typeof i === "boolean",
      null: (i) => i === null,
    }[value](instance);
    return ok ? [] : [{ path: [], schemaPath: ["type"] }];
  },
  minimum(ctx, value, instance) {
    if (!isNumber(instance)) return [];
    return instance >= value ? [] : [{ path: [], schemaPath: ["minimum"] }];
  },
  minLength(ctx, value, instance) {
    if (typeof instance !== "string") return [];
    return [...instance].length >= value ? [] : [{ path: [], schemaPath: ["minLength"] }];
  },
  properties(ctx, value, instance) {
    if (!isPlainObject(instance)) return [];
    const errs = [];
    for (const [k, sub] of Object.entries(value)) {
      if (k in instance) errs.push(...ctx.descend(instance[k], sub, [k], ["properties", k]));
    }
    return errs;
  },
  patternProperties(ctx, value, instance) {
    if (!isPlainObject(instance)) return [];
    const errs = [];
    for (const [p, sub] of Object.entries(value)) {
      const re = new RegExp(p);
      for (const k of Object.keys(instance)) {
        if (re.test(k)) errs.push(...ctx.descend(instance[k], sub, [k], ["patternProperties", p]));
      }
    }
    return errs;
  },
  additionalProperties(ctx, value, instance, schema) {
    if (!isPlainObject(instance)) return [];
    const props = isPlainObject(schema.properties) ? Object.keys(schema.properties) : [];
    const pats = isPlainObject(schema.patternProperties) ? Object.keys(schema.patternProperties).map((p) => new RegExp(p)) : [];
    const errs = [];
    for (const k of Object.keys(instance)) {
      if (props.includes(k) || pats.some((re) => re.test(k))) continue;
      if (value === false) errs.push({ path: [k], schemaPath: ["additionalProperties"] });
      else if (value !== true) errs.push(...ctx.descend(instance[k], value, [k], ["additionalProperties"]));
    }
    return errs;
  },
  prefixItems(ctx, value, instance) {
    if (!Array.isArray(instance)) return [];
    const errs = [];
    for (let i = 0; i < Math.min(value.length, instance.length); i++) {
      errs.push(...ctx.descend(instance[i], value[i], [i], ["prefixItems", i]));
    }
    return errs;
  },
  items(ctx, value, instance, schema) {
    if (!Array.isArray(instance)) return [];
    const start = Array.isArray(schema.prefixItems) ? schema.prefixItems.length : 0;
    const errs = [];
    for (let i = start; i < instance.length; i++) {
      errs.push(...ctx.descend(instance[i], value, [i], ["items"]));
    }
    return errs;
  },
  contains(ctx, value, instance) {
    if (!Array.isArray(instance)) return [];
    return instance.some((it) => ctx.isValid(it, value)) ? [] : [{ path: [], schemaPath: ["contains"] }];
  },
};

const ALL = { ...simple, ...keywords };

function makeCtx(schema) {
  const ctx = {
    isValid(instance, subschema) {
      return validate(instance, subschema).length === 0;
    },
    descend(instance, subschema, ip = [], sp = []) {
      return validate(instance, subschema).map((e) => ({
        path: [...ip, ...e.path],
        schemaPath: [...sp, ...e.schemaPath],
      }));
    },
  };
  return ctx;
}

function validate(instance, schema) {
  if (schema === true) return [];
  if (schema === false) return [{ path: [], schemaPath: [] }];
  const ctx = makeCtx(schema);
  const errs = [];
  for (const [k, fn] of Object.entries(ALL)) {
    if (k in schema) errs.push(...fn(ctx, schema[k], instance, schema));
  }
  return errs;
}

let failures = 0;
function check(name, instance, schema, expectedCount) {
  const n = validate(instance, schema).length;
  const ok = n === expectedCount;
  if (!ok) failures++;
  console.log(`${ok ? "PASS" : "FAIL"} ${name}: got ${n}, want ${expectedCount}`);
}

